gYH(){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc \u0628\u06c6 \u06a9\u06d5\u06cc\u0633 \u0648 \u062a\u06ce\u0686\u0648\u0648 \u0648 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06cc \u0646\u0648\u06ce"},
gYh(){return"\u0646\u0627\u0648\u0646\u06cc\u0634\u0627\u0646"},
gZg(){return"\u0698\u0645\u0627\u0631\u06d5\u06cc \u0645\u06c6\u0628\u0627\u06cc\u0644"},
gYz(){return"\u0646\u0627\u0633\u0646\u0627\u0645\u06d5\u06cc \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5 \u0686\u0627\u067e\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646"},
gYA(){return"\u0644\u06d5 \u067e\u0633\u0648\u06b5\u06d5\u06cc \u062f\u06a9\u062a\u06c6\u0631 \u0646\u06cc\u0634\u0627\u0646 \u062f\u06d5\u062f\u0631\u06ce\u062a\u060c \u0648\u06d5\u06a9 \u0695\u06d5\u0646\u06af\u06cc \u062a\u0627\u06cc\u0628\u06d5\u062a \u0644\u06d5\u0633\u06d5\u0631 \u0644\u06cc\u0628\u06b5\u06cc \u06a9\u06d5\u06cc\u0633 \u0648 \u062a\u06cc\u06a9\u06ce\u062a\u06cc QC."},
gZF(){return"\u0628\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u0644\u06c6\u06af\u06c6"},
